var mysql = require('mysql');
var host = "localhost";
var username = "root";
var password = "";

var options = {host:host,user:username,password:password,
    database:'datab',connectionLimit:5,queueLimit:0,waitForConnections:true};

var pool = mysql.createPool(options);
pool.getConnection(function(error, connection){
    if(error){
        return error;
    }
    //console.log('Connected!');    
});

module.exports = pool;